INSERT  IGNORE INTO `reviews` (`id`, `comment`, `created_at`, `rating_value`, `interview_slot_id`, `ratee_id`, `rater_id`) VALUES (1,'Hamza demonstrated exceptional Spring Boot knowledge. Solved our microservices design problem in under 20 minutes. Highly recommended.','2026-04-01 06:12:46.000000',5,1,201,101),(2,'Zara is a solid full-stack developer. Her Java knowledge is intermediate but she learns fast. Good communication throughout.','2026-04-01 06:12:46.000000',4,2,204,101),(3,'Ayesha is one of the best React developers we have interviewed. Her TypeScript and architecture knowledge is outstanding. Immediate hire.','2026-04-01 06:12:46.000000',5,3,202,102),(4,'Omar ML pipeline design was impressive. Strong theoretical background combined with production experience. Exactly what we needed.','2026-04-01 06:12:46.000000',5,5,203,103),(5,'Zara delivered a live coding challenge cleanly. Node.js and React integration was well thought out. A strong candidate.','2026-04-01 06:12:46.000000',4,7,204,101),(6,'Ali demonstrated solid Node.js and database skills. His Redis caching approach was clever. Would recommend for senior roles.','2026-04-01 06:12:46.000000',4,9,205,102),(7,'The interview was well-structured and technical. Sarah was professional and gave me detailed feedback afterwards. Great company culture.','2026-04-01 06:12:46.000000',5,1,101,201),(8,'Good interview process. Clear role expectations. The technical panel was knowledgeable. Minor point - the scheduling was a bit last minute.','2026-04-01 06:12:46.000000',4,2,101,204),(9,'Best interview experience I have had. Bilal was warm, the team was welcoming, and the role description matched exactly what was discussed.','2026-04-01 06:12:46.000000',5,3,102,202),(10,'Systems Limited clearly values engineering quality. The ML problem they gave was challenging but fair. Nida was very professional.','2026-04-01 06:12:46.000000',5,5,103,203),(11,'Second interview with TechVista was great. They clearly value full-stack talent. Live coding was fair and well-scoped.','2026-04-01 06:12:46.000000',4,7,101,204),(12,'Arbisoft has an excellent engineering culture. The Node.js problem was realistic and well-explained. Bilal gave constructive feedback.','2026-04-01 06:12:46.000000',4,9,102,205),(13,'strOng technical ability','2026-04-23 16:07:26.370390',5,62,306,104),(14,'Technically Robust but lacks communicational skills','2026-04-24 15:22:51.256146',5,12,204,6),(15,'Professional','2026-04-24 16:32:40.722479',5,4,102,204),(16,'','2026-04-24 17:28:01.189058',5,68,294,311),(17,'did nothing','2026-04-24 17:29:02.755782',1,70,282,311),(18,'','2026-04-26 15:46:51.028053',5,14,209,104),(19,'','2026-04-26 15:47:06.042845',5,14,104,209);
