--
-- Global detailed demo backfill for every user, candidate, employer, job,
-- match score, application, status history, and interview-related row.
--

SET SESSION group_concat_max_len = 1000000;

UPDATE `users` u
SET u.`phone_no` = COALESCE(NULLIF(u.`phone_no`, ''), CONCAT('+92 3', LPAD(MOD(u.`id` * 7919, 1000000000), 9, '0'))),
    u.`address` = COALESCE(NULLIF(u.`address`, ''), CONCAT(
        CASE MOD(u.`id`, 6)
            WHEN 0 THEN 'Gulberg, Lahore'
            WHEN 1 THEN 'Johar Town, Lahore'
            WHEN 2 THEN 'Clifton, Karachi'
            WHEN 3 THEN 'Blue Area, Islamabad'
            WHEN 4 THEN 'Saddar, Rawalpindi'
            ELSE 'University Road, Peshawar'
        END,
        ', Pakistan'
    )),
    u.`average_rating` = CASE
        WHEN u.`role` IN ('CANDIDATE', 'EMPLOYER') AND u.`average_rating` = 0
            THEN ROUND(3.2 + (MOD(u.`id`, 19) / 10), 2)
        ELSE u.`average_rating`
    END,
    u.`total_ratings` = CASE
        WHEN u.`role` IN ('CANDIDATE', 'EMPLOYER') AND u.`total_ratings` = 0
            THEN 1 + MOD(u.`id`, 9)
        ELSE u.`total_ratings`
    END,
    u.`created_at` = COALESCE(u.`created_at`, DATE_ADD('2026-04-01 09:00:00.000000', INTERVAL MOD(u.`id`, 28) DAY)),
    u.`updated_at` = COALESCE(u.`updated_at`, DATE_ADD(COALESCE(u.`created_at`, '2026-04-01 09:00:00.000000'), INTERVAL 1 + MOD(u.`id`, 12) DAY)),
    u.`email_verified` = b'1',
    u.`failed_login_attempts` = 0
WHERE u.`role` IN ('CANDIDATE', 'EMPLOYER', 'ADMIN');

UPDATE `employers` e
JOIN `users` u ON u.`id` = e.`id`
SET e.`company_name` = COALESCE(NULLIF(e.`company_name`, ''), CONCAT(SUBSTRING_INDEX(u.`name`, ' ', 1), ' Technologies')),
    e.`company_location` = COALESCE(NULLIF(e.`company_location`, ''), CONCAT(
        CASE MOD(e.`id`, 5)
            WHEN 0 THEN 'Lahore'
            WHEN 1 THEN 'Karachi'
            WHEN 2 THEN 'Islamabad'
            WHEN 3 THEN 'Rawalpindi'
            ELSE 'Peshawar'
        END,
        ', Pakistan'
    )),
    e.`company_details` = COALESCE(NULLIF(e.`company_details`, ''), CONCAT(
        COALESCE(NULLIF(e.`company_name`, ''), CONCAT(SUBSTRING_INDEX(u.`name`, ' ', 1), ' Technologies')),
        ' hires software engineers, product builders, data specialists, and operations teams for client-facing delivery.'
    ));

UPDATE `candidates` c
JOIN `users` u ON u.`id` = c.`id`
LEFT JOIN (
    SELECT ms.`candidate_id`,
           SUBSTRING_INDEX(GROUP_CONCAT(jp.`required_skills` ORDER BY ms.`match_percentage` DESC SEPARATOR ','), ',', 12) AS `best_skills`
    FROM `match_scores` ms
    JOIN `job_postings` jp ON jp.`id` = ms.`job_posting_id`
    GROUP BY ms.`candidate_id`
) skill_source ON skill_source.`candidate_id` = c.`id`
SET c.`cv_file_path` = COALESCE(NULLIF(c.`cv_file_path`, ''), CONCAT('uploads/cvs/demo-candidate-', c.`id`, '.pdf')),
    c.`parsed_skills` = COALESCE(NULLIF(c.`parsed_skills`, ''), skill_source.`best_skills`, 'Java,Spring Boot,React,SQL,REST API,Git,Docker'),
    c.`preferred_location` = COALESCE(NULLIF(c.`preferred_location`, ''), CASE MOD(c.`id`, 6)
        WHEN 0 THEN 'Lahore'
        WHEN 1 THEN 'Karachi'
        WHEN 2 THEN 'Islamabad'
        WHEN 3 THEN 'Rawalpindi'
        WHEN 4 THEN 'Peshawar'
        ELSE 'Remote'
    END),
    c.`preferred_shift` = COALESCE(NULLIF(c.`preferred_shift`, ''), CASE MOD(c.`id`, 3)
        WHEN 0 THEN 'DAY'
        WHEN 1 THEN 'NIGHT'
        ELSE 'DAY'
    END),
    c.`work_type` = COALESCE(NULLIF(c.`work_type`, ''), CASE MOD(c.`id`, 3)
        WHEN 0 THEN 'REMOTE'
        WHEN 1 THEN 'HYBRID'
        ELSE 'ON_SITE'
    END),
    c.`profile_views` = CASE WHEN c.`profile_views` = 0 THEN 8 + MOD(c.`id` * 7, 90) ELSE c.`profile_views` END;

UPDATE `job_postings` jp
SET jp.`created_at` = COALESCE(jp.`created_at`, DATE_ADD('2026-04-01 10:00:00.000000', INTERVAL MOD(jp.`id`, 35) DAY)),
    jp.`location` = COALESCE(NULLIF(jp.`location`, ''), CASE MOD(jp.`id`, 6)
        WHEN 0 THEN 'Lahore'
        WHEN 1 THEN 'Karachi'
        WHEN 2 THEN 'Islamabad'
        WHEN 3 THEN 'Rawalpindi'
        WHEN 4 THEN 'Peshawar'
        ELSE 'Remote'
    END),
    jp.`shift` = COALESCE(NULLIF(jp.`shift`, ''), CASE MOD(jp.`id`, 3) WHEN 0 THEN 'DAY' WHEN 1 THEN 'NIGHT' ELSE 'DAY' END),
    jp.`experience_years` = COALESCE(jp.`experience_years`, 1 + MOD(jp.`id`, 5)),
    jp.`status` = COALESCE(jp.`status`, 'OPEN');

INSERT INTO `hiring_prompts` (`raw_text`, `submission_date`, `employer_id`, `job_posting_id`, `parsed_skills`, `parsed_location`, `parsed_shift`, `parsed_experience_years`)
SELECT CONCAT(
           'Need a ', LOWER(jp.`job_title`), ' for ', COALESCE(jp.`location`, 'Pakistan'),
           ', ', LOWER(COALESCE(jp.`shift`, 'DAY')), ' shift. Required skills: ',
           jp.`required_skills`, '. Minimum ', COALESCE(jp.`experience_years`, 1), ' years experience.'
       ),
       COALESCE(jp.`created_at`, '2026-04-01 10:00:00.000000'),
       jp.`employer_id`,
       jp.`id`,
       jp.`required_skills`,
       jp.`location`,
       jp.`shift`,
       jp.`experience_years`
FROM `job_postings` jp
ON DUPLICATE KEY UPDATE
    `parsed_skills` = VALUES(`parsed_skills`),
    `parsed_location` = VALUES(`parsed_location`),
    `parsed_shift` = VALUES(`parsed_shift`),
    `parsed_experience_years` = VALUES(`parsed_experience_years`),
    `submission_date` = COALESCE(`hiring_prompts`.`submission_date`, VALUES(`submission_date`));

INSERT IGNORE INTO `match_scores` (`id`, `location_matched`, `match_percentage`, `ranking`, `shift_matched`, `skill_match_pct`, `candidate_id`, `job_posting_id`)
SELECT 4000000 + missing_candidates.`candidate_id` * 100 + seed_jobs.`rn`,
       CASE WHEN LOWER(COALESCE(c.`preferred_location`, '')) = LOWER(COALESCE(seed_jobs.`location`, '')) THEN b'1' ELSE b'0' END,
       45 + MOD(missing_candidates.`candidate_id` + seed_jobs.`job_posting_id` + seed_jobs.`rn`, 51),
       seed_jobs.`rn`,
       CASE WHEN LOWER(COALESCE(c.`preferred_shift`, '')) = LOWER(COALESCE(seed_jobs.`shift`, '')) THEN b'1' ELSE b'0' END,
       48 + MOD(missing_candidates.`candidate_id` + seed_jobs.`job_posting_id`, 45),
       missing_candidates.`candidate_id`,
       seed_jobs.`job_posting_id`
FROM (
    SELECT c0.`id` AS `candidate_id`
    FROM `candidates` c0
    LEFT JOIN `match_scores` existing ON existing.`candidate_id` = c0.`id`
    WHERE existing.`id` IS NULL
) missing_candidates
JOIN `candidates` c ON c.`id` = missing_candidates.`candidate_id`
JOIN (
    SELECT ranked_jobs.`job_posting_id`, ranked_jobs.`location`, ranked_jobs.`shift`, ranked_jobs.`rn`
    FROM (
        SELECT jp.`id` AS `job_posting_id`,
               jp.`location`,
               jp.`shift`,
               ROW_NUMBER() OVER (ORDER BY jp.`id`) AS `rn`
        FROM `job_postings` jp
        WHERE jp.`status` = 'OPEN'
    ) ranked_jobs
    WHERE ranked_jobs.`rn` <= 8
) seed_jobs
LEFT JOIN `match_scores` duplicate_check
    ON duplicate_check.`candidate_id` = missing_candidates.`candidate_id`
   AND duplicate_check.`job_posting_id` = seed_jobs.`job_posting_id`
WHERE duplicate_check.`id` IS NULL;

INSERT IGNORE INTO `match_scores` (`id`, `location_matched`, `match_percentage`, `ranking`, `shift_matched`, `skill_match_pct`, `candidate_id`, `job_posting_id`)
SELECT 4100000 + missing_jobs.`job_posting_id` * 100 + seed_candidates.`rn`,
       CASE WHEN LOWER(COALESCE(seed_candidates.`preferred_location`, '')) = LOWER(COALESCE(missing_jobs.`location`, '')) THEN b'1' ELSE b'0' END,
       42 + MOD(missing_jobs.`job_posting_id` + seed_candidates.`candidate_id` + seed_candidates.`rn`, 54),
       seed_candidates.`rn`,
       CASE WHEN LOWER(COALESCE(seed_candidates.`preferred_shift`, '')) = LOWER(COALESCE(missing_jobs.`shift`, '')) THEN b'1' ELSE b'0' END,
       46 + MOD(missing_jobs.`job_posting_id` + seed_candidates.`candidate_id`, 47),
       seed_candidates.`candidate_id`,
       missing_jobs.`job_posting_id`
FROM (
    SELECT jp0.`id` AS `job_posting_id`, jp0.`location`, jp0.`shift`
    FROM `job_postings` jp0
    LEFT JOIN `match_scores` existing ON existing.`job_posting_id` = jp0.`id`
    WHERE existing.`id` IS NULL
) missing_jobs
JOIN (
    SELECT ranked_candidates.`candidate_id`, ranked_candidates.`preferred_location`, ranked_candidates.`preferred_shift`, ranked_candidates.`rn`
    FROM (
        SELECT c.`id` AS `candidate_id`,
               c.`preferred_location`,
               c.`preferred_shift`,
               ROW_NUMBER() OVER (ORDER BY c.`profile_views` DESC, c.`id`) AS `rn`
        FROM `candidates` c
    ) ranked_candidates
    WHERE ranked_candidates.`rn` <= 8
) seed_candidates
LEFT JOIN `match_scores` duplicate_check
    ON duplicate_check.`candidate_id` = seed_candidates.`candidate_id`
   AND duplicate_check.`job_posting_id` = missing_jobs.`job_posting_id`
WHERE duplicate_check.`id` IS NULL;

UPDATE `match_scores` ms
JOIN `candidates` c ON c.`id` = ms.`candidate_id`
JOIN `job_postings` jp ON jp.`id` = ms.`job_posting_id`
SET ms.`location_matched` = CASE WHEN LOWER(COALESCE(c.`preferred_location`, '')) = LOWER(COALESCE(jp.`location`, '')) THEN b'1' ELSE b'0' END,
    ms.`shift_matched` = CASE WHEN LOWER(COALESCE(c.`preferred_shift`, '')) = LOWER(COALESCE(jp.`shift`, '')) THEN b'1' ELSE b'0' END,
    ms.`skill_match_pct` = LEAST(100, GREATEST(0, COALESCE(ms.`skill_match_pct`, ms.`match_percentage`) + MOD(ms.`id`, 9) - 4));

INSERT INTO `applications` (`candidate_id`, `job_posting_id`, `status`, `created_at`, `updated_at`)
SELECT x.`candidate_id`,
       x.`job_posting_id`,
       x.`demo_status`,
       x.`demo_created_at`,
       DATE_ADD(x.`demo_created_at`, INTERVAL CASE x.`demo_status`
           WHEN 'RECOMMENDED' THEN 0
           WHEN 'SHORTLISTED' THEN 2
           WHEN 'SCHEDULED' THEN 5
           WHEN 'CONFIRMED' THEN 6
           WHEN 'COMPLETED' THEN 10
           WHEN 'REVIEWED' THEN 12
           WHEN 'HIRED' THEN 15
           WHEN 'REJECTED' THEN 4
           ELSE 0
       END DAY)
FROM (
    SELECT ms.`candidate_id`,
           ms.`job_posting_id`,
           DATE_ADD(COALESCE(jp.`created_at`, '2026-04-01 10:00:00.000000'), INTERVAL ms.`ranking` + MOD(ms.`candidate_id`, 7) MINUTE) AS `demo_created_at`,
           CASE
               WHEN ms.`match_percentage` < 40 AND MOD(ms.`candidate_id` + ms.`job_posting_id`, 3) <> 1 THEN 'REJECTED'
               WHEN MOD(ms.`candidate_id` + ms.`job_posting_id`, 29) = 0 THEN 'HIRED'
               WHEN MOD(ms.`candidate_id` + ms.`job_posting_id`, 23) = 0 THEN 'REVIEWED'
               WHEN MOD(ms.`candidate_id` + ms.`job_posting_id`, 19) = 0 THEN 'COMPLETED'
               WHEN MOD(ms.`candidate_id` + ms.`job_posting_id`, 17) = 0 THEN 'CONFIRMED'
               WHEN MOD(ms.`candidate_id` + ms.`job_posting_id`, 13) = 0 THEN 'SCHEDULED'
               WHEN MOD(ms.`candidate_id` + ms.`job_posting_id`, 7) = 0 OR ms.`ranking` <= 2 THEN 'SHORTLISTED'
               ELSE 'RECOMMENDED'
           END AS `demo_status`
    FROM `match_scores` ms
    JOIN `job_postings` jp ON jp.`id` = ms.`job_posting_id`
) x
ON DUPLICATE KEY UPDATE
    `status` = VALUES(`status`),
    `created_at` = VALUES(`created_at`),
    `updated_at` = VALUES(`updated_at`);

DELETE FROM `application_status_history`
WHERE `source` = 'LEGACY_BACKFILL'
   OR `source` LIKE 'DEMO_%';

INSERT INTO `application_status_history` (`application_id`, `previous_status`, `new_status`, `actor_email`, `source`, `changed_at`)
SELECT a.`id`, NULL, 'RECOMMENDED', 'system@swifthire.local', 'DEMO_ATS_MATCH', a.`created_at`
FROM `applications` a
UNION ALL
SELECT a.`id`, 'RECOMMENDED', 'SHORTLISTED', eu.`email`, 'DEMO_EMPLOYER_ACTION', DATE_ADD(a.`created_at`, INTERVAL 2 DAY)
FROM `applications` a
JOIN `job_postings` jp ON jp.`id` = a.`job_posting_id`
JOIN `users` eu ON eu.`id` = jp.`employer_id`
WHERE a.`status` IN ('SHORTLISTED', 'SCHEDULED', 'CONFIRMED', 'COMPLETED', 'REVIEWED', 'HIRED')
UNION ALL
SELECT a.`id`, 'RECOMMENDED', 'REJECTED', eu.`email`, 'DEMO_EMPLOYER_ACTION', DATE_ADD(a.`created_at`, INTERVAL 4 DAY)
FROM `applications` a
JOIN `job_postings` jp ON jp.`id` = a.`job_posting_id`
JOIN `users` eu ON eu.`id` = jp.`employer_id`
WHERE a.`status` = 'REJECTED'
UNION ALL
SELECT a.`id`, 'SHORTLISTED', 'SCHEDULED', eu.`email`, 'DEMO_INTERVIEW_SCHEDULING', DATE_ADD(a.`created_at`, INTERVAL 5 DAY)
FROM `applications` a
JOIN `job_postings` jp ON jp.`id` = a.`job_posting_id`
JOIN `users` eu ON eu.`id` = jp.`employer_id`
WHERE a.`status` IN ('SCHEDULED', 'CONFIRMED', 'COMPLETED', 'REVIEWED', 'HIRED')
UNION ALL
SELECT a.`id`, 'SCHEDULED', 'CONFIRMED', cu.`email`, 'DEMO_CANDIDATE_CONFIRMATION', DATE_ADD(a.`created_at`, INTERVAL 6 DAY)
FROM `applications` a
JOIN `users` cu ON cu.`id` = a.`candidate_id`
WHERE a.`status` IN ('CONFIRMED', 'COMPLETED', 'REVIEWED', 'HIRED')
UNION ALL
SELECT a.`id`, 'CONFIRMED', 'COMPLETED', 'scheduler@swifthire.local', 'DEMO_SCHEDULER', DATE_ADD(a.`created_at`, INTERVAL 10 DAY)
FROM `applications` a
WHERE a.`status` IN ('COMPLETED', 'REVIEWED', 'HIRED')
UNION ALL
SELECT a.`id`, 'COMPLETED', 'REVIEWED', eu.`email`, 'DEMO_REVIEW_SUBMITTED', DATE_ADD(a.`created_at`, INTERVAL 12 DAY)
FROM `applications` a
JOIN `job_postings` jp ON jp.`id` = a.`job_posting_id`
JOIN `users` eu ON eu.`id` = jp.`employer_id`
WHERE a.`status` IN ('REVIEWED', 'HIRED')
UNION ALL
SELECT a.`id`, 'REVIEWED', 'HIRED', eu.`email`, 'DEMO_HIRE_FLOW', DATE_ADD(a.`created_at`, INTERVAL 15 DAY)
FROM `applications` a
JOIN `job_postings` jp ON jp.`id` = a.`job_posting_id`
JOIN `users` eu ON eu.`id` = jp.`employer_id`
WHERE a.`status` = 'HIRED';

DELETE FROM `reviews`
WHERE `id` BETWEEN 3000000 AND 3999999;

DELETE FROM `interview_slots`
WHERE `id` BETWEEN 2000000 AND 2999999;

DELETE FROM `interview_windows`
WHERE `id` BETWEEN 2000000 AND 2999999;

INSERT INTO `interview_windows` (`id`, `date`, `start_time`, `end_time`, `employer_id`)
SELECT 2000000 + x.`application_id`,
       DATE(x.`slot_start`),
       TIME(x.`slot_start`),
       TIME(DATE_ADD(x.`slot_start`, INTERVAL 45 MINUTE)),
       x.`employer_id`
FROM (
    SELECT a.`id` AS `application_id`,
           jp.`employer_id`,
           CASE
               WHEN a.`status` IN ('SCHEDULED', 'CONFIRMED')
                   THEN TIMESTAMP(DATE_ADD('2026-05-12', INTERVAL MOD(a.`id`, 14) DAY), MAKETIME(9 + MOD(a.`id`, 8), IF(MOD(a.`id`, 2) = 0, 0, 30), 0))
               ELSE TIMESTAMP(DATE_ADD('2026-04-20', INTERVAL MOD(a.`id`, 14) DAY), MAKETIME(9 + MOD(a.`id`, 8), IF(MOD(a.`id`, 2) = 0, 0, 30), 0))
           END AS `slot_start`
    FROM `applications` a
    JOIN `job_postings` jp ON jp.`id` = a.`job_posting_id`
    WHERE a.`status` IN ('SCHEDULED', 'CONFIRMED', 'COMPLETED', 'REVIEWED', 'HIRED')
) x;

INSERT INTO `interview_slots` (`id`, `calendly_link`, `end_time`, `reminder_sent1d`, `reminder_sent3d`, `reminder_sent7d`, `start_time`, `status`, `candidate_id`, `job_posting_id`, `window_id`)
SELECT 2000000 + x.`application_id`,
       CONCAT('https://meet.jit.si/swifthire-demo-', x.`application_id`),
       DATE_ADD(x.`slot_start`, INTERVAL 45 MINUTE),
       CASE WHEN x.`slot_status` = 'COMPLETED' THEN b'1' ELSE b'0' END,
       CASE WHEN x.`slot_status` = 'COMPLETED' THEN b'1' ELSE b'0' END,
       CASE WHEN x.`slot_status` = 'COMPLETED' THEN b'1' ELSE b'0' END,
       x.`slot_start`,
       x.`slot_status`,
       x.`candidate_id`,
       x.`job_posting_id`,
       2000000 + x.`application_id`
FROM (
    SELECT a.`id` AS `application_id`,
           a.`candidate_id`,
           a.`job_posting_id`,
           CASE
               WHEN a.`status` = 'SCHEDULED' THEN 'PENDING'
               WHEN a.`status` = 'CONFIRMED' THEN 'CONFIRMED'
               ELSE 'COMPLETED'
           END AS `slot_status`,
           CASE
               WHEN a.`status` IN ('SCHEDULED', 'CONFIRMED')
                   THEN TIMESTAMP(DATE_ADD('2026-05-12', INTERVAL MOD(a.`id`, 14) DAY), MAKETIME(9 + MOD(a.`id`, 8), IF(MOD(a.`id`, 2) = 0, 0, 30), 0))
               ELSE TIMESTAMP(DATE_ADD('2026-04-20', INTERVAL MOD(a.`id`, 14) DAY), MAKETIME(9 + MOD(a.`id`, 8), IF(MOD(a.`id`, 2) = 0, 0, 30), 0))
           END AS `slot_start`
    FROM `applications` a
    WHERE a.`status` IN ('SCHEDULED', 'CONFIRMED', 'COMPLETED', 'REVIEWED', 'HIRED')
) x;

INSERT IGNORE INTO `reviews` (`id`, `comment`, `created_at`, `rating_value`, `interview_slot_id`, `ratee_id`, `rater_id`)
SELECT 3000000 + a.`id`,
       CONCAT('Seeded interview review for ', cu.`name`, ' on ', jp.`job_title`, '. Strong practical fit with clear communication and relevant project experience.'),
       DATE_ADD(s.`end_time`, INTERVAL 1 HOUR),
       4 + MOD(a.`id`, 2),
       s.`id`,
       a.`candidate_id`,
       jp.`employer_id`
FROM `applications` a
JOIN `interview_slots` s ON s.`id` = 2000000 + a.`id`
JOIN `job_postings` jp ON jp.`id` = a.`job_posting_id`
JOIN `users` cu ON cu.`id` = a.`candidate_id`
WHERE a.`status` IN ('REVIEWED', 'HIRED');

UPDATE `candidates` c
JOIN `applications` a ON a.`candidate_id` = c.`id` AND a.`status` = 'HIRED'
JOIN `job_postings` jp ON jp.`id` = a.`job_posting_id`
JOIN `employers` e ON e.`id` = jp.`employer_id`
JOIN `users` eu ON eu.`id` = e.`id`
SET c.`hired_at` = a.`updated_at`,
    c.`hired_company_name` = e.`company_name`,
    c.`hired_employer_email` = eu.`email`,
    c.`hired_job_title` = jp.`job_title`;

