-- These keep the visible candidate application list from looking like legacy
-- backfilled data where every stored application is only RECOMMENDED.
--

DELETE FROM `application_status_history`
WHERE `application_id` IN (
  SELECT `id`
  FROM `applications`
  WHERE `candidate_id` = 242
    AND `job_posting_id` IN (1, 7, 30, 31, 32, 35, 54, 57, 67, 69, 75, 117)
);

DELETE FROM `interview_slots`
WHERE `id` BETWEEN 13001 AND 13004
   OR (`candidate_id` = 242 AND `job_posting_id` IN (1, 35, 54, 69));

DELETE FROM `interview_windows`
WHERE `id` BETWEEN 13001 AND 13004;

